    if (p === 'yesterday') return { from: new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1), to: new Date(now.getFullYear(), now.getMonth(), now.getDate()) };
    if (p === '7d') return { from: new Date(now.getFullYear(), now.getMonth(), now.getDate() - 6), to: fimHoje };
    if (p === '15d') return { from: new Date(now.getFullYear(), now.getMonth(), now.getDate() - 14), to: fimHoje };
    if (p === '30d') return { from: new Date(now.getFullYear(), now.getMonth(), now.getDate() - 29), to: fimHoje };
    if (p === 'month') return { from: new Date(now.getFullYear(), now.getMonth(), 1), to: fimHoje };
    if (p === 'prevmonth') return { from: new Date(now.getFullYear(), now.getMonth() - 1, 1), to: new Date(now.getFullYear(), now.getMonth(), 1) };
