    var semOrigem = [], foraCobertura = [];
    semMatch.forEach(function (t) { var inCov = walletInCoverage(t, wEffCat(t), coverage); if (inCov === false || inCov === null) foraCobertura.push(t); else semOrigem.push(t); });
