    var strip2 = MetricGrid([MetricCard({ label: 'Pedidos cancelados', value: nn(t.cancelled), cls: 'amber', sub: pct(r2(t.orders ? t.cancelled / t.orders * 100 : 0)) }), MetricCard({ label: 'Reembolso', value: brlU(t.refund), cls: 'red' }), MetricCard({ label: 'Concluídos', value: nn(t.concluded), cls: 'green' }), MetricCard({ label: 'Lucro real (pedidos c/ custo)', value: lucroN ? brlU(lucroKnown) : 'sem base', cls: lucroKnown >= 0 ? 'green' : 'red', sub: lucroN ? nn(lucroN) + ' pedidos' : 'importe custos em Produtos' }), MetricCard({ label: 'Comissão média/pedido', value: brlU(t.orders ? Math.round(t.comAff / t.orders) : 0), cls: 'blue' }), MetricCard({ label: 'Taxa média ponderada', value: pct(r2(t.sales ? t.comAff / t.sales * 100 : 0)), cls: 'amber' })]);
