    var topChart = topSales.length ? chartCard('Top afiliados por vendas', legendSwatch([['Vendas', '#2b4bd6']]), svgHBars(topSales.map(function (a) { return { label: a.user, value: a.sales / 10000 }; }), { fmt: function (v) { return brl(v); } })) : '';
