    var custoCoveragePct = custoItemsTotal ? r2(custoItemsKnown / custoItemsTotal * 100) : 0;
    // Refatoração M3 (Fase 3 item 3): adjTot agora respeita o período selecionado (Dia/Semana/Mês/
    // Personalizado), filtrando mrAdj pela "Data de conclusão do ajuste" real da planilha (ver
    // mrParseIncome acima). Ajustes sem data reconhecida (importados antes desta correção, ou linha
    // sem data capturável na fonte) ficam de fora da soma do período — nunca somados "no escuro" — mas
    // continuam contados em adjSemData para o rótulo nunca esconder essa lacuna.
    var adjComData = mrAdj.filter(function (a) { return a.data; });
    var adjNoPeriodoArr = adjComData.filter(function (a) { return within(a.data); });
    var adjTotPeriodo = adjNoPeriodoArr.reduce(function (s, a) { return s + a.valor; }, 0);
    var adjSemData = mrAdj.length - adjComData.length;
