          if (wtxDev.length) { devolucoesFallbackC += Math.round(wtxDev.reduce(function (s, t) { return s + t.amount; }, 0) * 100); devolucoesFallbackN++; devolucoesFallbackOrigem = devolucoesFallbackOrigem || 'CARTEIRA'; }
