      var catTxt = r.cp && r.cp.categoryId ? esc(cpCategoryLabel(r.cp.categoryId)) : '<span class="footnote" style="margin:0">—</span>';
      return '<tr><td class="mono rowlink" data-goped360="' + esc(r.orderId) + '">' + esc(r.orderId) + '</td><td>Despesa</td><td>' + catTxt + '</td><td>' + statusTag + '</td><td class="nowrap ' + (r.valor < 0 ? 'neg' : 'pos') + '">' + brlC(r.valor) + '</td><td>' + (r.cp ? '<button class="btn-sm" data-cpedit="' + esc(r.cp.id) + '">Alterar</button>' : '<span class="footnote" style="margin:0">—</span>') + '</td></tr>';
