  function caixaDiasComMovimento() {
    var days = {};
    orders.forEach(function (o) { if (o.paidAt) days[o.paidAt.slice(0, 10)] = 1; });
    expSessions.forEach(function (s) { days[s.dataOperacional] = 1; });
    if (acelera.length) aceleraByDia(acelera).forEach(function (d) { days[d.data] = 1; });
    return Object.keys(days).sort().reverse();
  }
  // ---- ciclo de vida do fechamento — mesmo padrão já aprovado em walletCloseDay/walletDayStatus,
  // agora escopado ao núcleo Pedidos+Expedição+Acelera+Financeiro (não só à Carteira). ----
  // PROMPT "OTIMIZAÇÃO COMPLETA DE UX/UI DESKTOP" §5/§9: status visual padronizado 🟢/🟡/🔴 — só
  // troca o texto do rótulo (emoji), a lógica de status (caixaDayStatus) continua exatamente a mesma.
  var CAIXA_LABEL = { ABERTO: ['🟡 Em conferência', 'neutral'], FECHADO: ['🟢 Fechado', 'ok'], FECHADO_COM_RESSALVA: ['🟡 Fechado com ressalva', 'warn'], REVISAO_NECESSARIA: ['🔴 Revisão necessária', 'warn'] };
  function caixaDayStatus(dateKey) {
    var pend = caixaDayPendencias(dateKey);
    var pendCart = caixaDayPendenciasCarteira(dateKey);
    var rec = caixaClose[dateKey] || null;
    var closed = rec && (rec.status === 'FECHADO' || rec.status === 'FECHADO_COM_RESSALVA');
    // §20-21: fechamento é uma fotografia — se pendências mudaram de contagem depois de fechado
    // (movimento posterior), nunca reescreve o snapshot; só sinaliza revisão necessária. Camada 4
    // (Carteira) entra na mesma checagem — as duas famílias de pendência protegem o fechamento.
    var novoDepois = !!(closed && rec.snapshot && (rec.snapshot.pendTotal !== pend.total || (rec.snapshot.pendCartTotal || 0) !== pendCart.total));
    var status = !closed ? 'ABERTO' : (novoDepois ? 'REVISAO_NECESSARIA' : rec.status);
    return { pend: pend, pendCart: pendCart, rec: rec, novoDepois: novoDepois, status: status };
  }
  // ============================================================ INTEGRAÇÃO FINANCEIRA DO FECHAMENTO
  // Fases 5-8 do "PROMPT MESTRE — REESTRUTURAÇÃO DEFINITIVA DO CAIXA...": ao fechar o dia, gera/
  // atualiza — de forma IDEMPOTENTE, sempre por sourceEventKey — os recebíveis (Contas a Receber), as
  // despesas já retidas/pagas pela Shopee (Contas a Pagar) e as transferências para o banco
  // (financialTransfer). Reaproveita 100% dos motores canônicos já aprovados desta sessão
  // (pedidoComposicaoFinanceira, aceleraResultadoFechamento, caixaDayMovimentosPosteriores/
  // caixaMovCategoria, caixaDayTransferenciasBancarias) — nunca recalcula nada em paralelo. Chamar de
  // novo para o MESMO dia só ATUALIZA os mesmos registros (nunca duplica) — é o que garante
  // fechar→reabrir→fechar sem duplicidade (teste obrigatório da Fase 17).
  //
  // Montagem do PLANO é pura (não persiste nada) — usada tanto pelo preview "Resumo da integração
  // financeira" (Fase 13) quanto pela aplicação real no fechamento (Fase 8): o plano é idêntico nos
