    var tot = { n: 0, vendaBrutaC: 0, taxasMarketplaceC: 0, custoProdutoC: 0, horaHomemC: 0, custosFixosAbsorvidosC: 0, custosVariaveisC: 0, impostoC: 0, lucroRealC: 0, vendaBrutaComResultadoC: 0, custoPendenteN: 0, nComResultado: 0, itens: [] };
    aggs.forEach(function (a) { tot.n += a.n; tot.vendaBrutaC += a.vendaBrutaC; tot.taxasMarketplaceC += a.taxasMarketplaceC; tot.custoProdutoC += a.custoProdutoC; tot.horaHomemC += a.horaHomemC; tot.custosFixosAbsorvidosC += a.custosFixosAbsorvidosC; tot.custosVariaveisC += a.custosVariaveisC; tot.impostoC += a.impostoC; if (a.lucroRealC != null) tot.lucroRealC += a.lucroRealC; tot.vendaBrutaComResultadoC += a.vendaBrutaComResultadoC; tot.nComResultado += a.nComResultado; tot.custoPendenteN += a.custoPendenteN; tot.itens = tot.itens.concat(a.itens); });
