  // ==================== FASE 9 V7/V9 — "Lupa" de sugestão de categorias (CP) ====================
  // Biblioteca de MODELOS DETERMINÍSTICOS — nenhuma IA/LLM decide a estrutura financeira. O operador
  // sempre vê a lista completa antes de qualquer gravação, escolhe o que quer (checkbox) e confirma
  // numa segunda tela ("Deseja cadastrar N categorias dentro de X? Cancelar/Confirmar") — nada é
  // criado automaticamente sem essas duas confirmações explícitas.
  var CP_SUGESTAO_TEMPLATES = {
    'Folha de Pagamento': ['Salários', 'Décimo Terceiro', 'Férias', 'FGTS', 'INSS Patronal', 'Vale Transporte', 'Vale Alimentação', 'Rescisões'],
    'Impostos': ['Simples Nacional', 'ICMS', 'ISS', 'IRPJ', 'CSLL', 'PIS/COFINS'],
    'Despesas Fixas': ['Aluguel', 'Energia Elétrica', 'Água', 'Internet', 'Telefone', 'Condomínio'],
    'Marketing': ['Anúncios Shopee Ads', 'Anúncios Redes Sociais', 'Influenciadores', 'Material Gráfico'],
    'Logística': ['Frete', 'Embalagens', 'Transportadora', 'Combustível'],
    'Produção': ['Matéria-Prima', 'Mão de Obra Direta', 'Manutenção de Máquinas', 'Insumos'],
    'Administrativo': ['Material de Escritório', 'Contabilidade', 'Serviços Jurídicos', 'Limpeza'],
    'Tecnologia': ['Software/Assinaturas', 'Hospedagem', 'Equipamentos de TI', 'Suporte Técnico'],
    'Financeiro': ['Tarifas Bancárias', 'Juros e Multas', 'IOF', 'Taxas de Antecipação'],
    'Comercial': ['Comissão de Vendedores', 'Brindes', 'Amostras', 'Viagens Comerciais'],
  };
  // Duplicidade é verificada em TODO cpCategories (qualquer centro) — mesmo padrão de "nunca duplicar
  // silenciosamente" já usado no cadastro manual (V2). Item com nome já existente nasce DESMARCADO,
  // com aviso de onde já está; o operador decide se ainda assim quer criar um novo (marcar de novo).
  function cpCategoriaExistenteEm(nome) {
    var n = cpNorm(nome);
    var achado = cpCategories.find(function (c) { return cpNorm(c.name) === n; });
    return achado ? cpCostCenterLabel(achado.costCenterId) : null;
  }
  function cpSugestaoChecklistHtml(tplKey) {
    var itens = CP_SUGESTAO_TEMPLATES[tplKey] || [];
    return itens.map(function (nome) {
      var existeEm = cpCategoriaExistenteEm(nome);
      return '<label class="fld" style="display:flex;align-items:flex-start;gap:8px;font-weight:400;margin-top:4px">' +
        '<input type="checkbox" class="cps-item" value="' + esc(nome) + '"' + (existeEm ? '' : ' checked') + ' style="margin-top:3px">' +
        '<span>' + esc(nome) + (existeEm ? ' <span class="footnote" style="margin:0;color:var(--warn,#b06a00)">— já existe em "' + esc(existeEm) + '"</span>' : '') + '</span></label>';
    }).join('');
  }
  function openCpSugerirCategoriasModal(centro) {
    if (!centro) return;
    var chaves = Object.keys(CP_SUGESTAO_TEMPLATES);
    var matchKey = chaves.find(function (k) { return cpNorm(k) === cpNorm(centro.name); }) || chaves[0];
    var bodyHtml =
      '<p class="footnote" style="margin:0 0 10px">Modelo determinístico — nada é gravado até você confirmar na próxima tela.</p>' +
      '<label class="fld">Modelo de categorias</label><select class="select" id="cps-tpl" style="width:100%">' + chaves.map(function (k) { return '<option value="' + esc(k) + '"' + (k === matchKey ? ' selected' : '') + '>' + esc(k) + '</option>'; }).join('') + '</select>' +
      '<div id="cps-checklist" style="margin-top:10px">' + cpSugestaoChecklistHtml(matchKey) + '</div>';
    var mdl = openModal({
      title: '🔍 Sugerir categorias — ' + centro.name, width: 460, bodyHtml: bodyHtml, confirmLabel: 'Continuar',
      onMount: function (panel) {
        var sel = panel.querySelector('#cps-tpl');
        if (sel) sel.onchange = function () { panel.querySelector('#cps-checklist').innerHTML = cpSugestaoChecklistHtml(sel.value); };
      },
      onConfirm: function (panel) {
        var nomes = Array.from(panel.querySelectorAll('.cps-item:checked')).map(function (cb) { return cb.value; });
        if (!nomes.length) { toast('Selecione ao menos uma categoria', '', true); return false; }
        mdl.close();
        openCpConfirmarSugestaoModal(centro, nomes);
      },
    });
  }
  function openCpConfirmarSugestaoModal(centro, nomes) {
    var bodyHtml = '<p>Deseja cadastrar <b>' + nomes.length + '</b> categoria' + (nomes.length > 1 ? 's' : '') + ' dentro de "' + esc(centro.name) + '"?</p>' +
      '<ul style="margin:8px 0 0 18px;padding:0">' + nomes.map(function (n) { return '<li>' + esc(n) + '</li>'; }).join('') + '</ul>';
    openModal({
      title: 'Confirmar criação de categorias', width: 420, bodyHtml: bodyHtml, confirmLabel: 'Confirmar',
      onConfirm: function () {
        var now = new Date().toISOString();
        var full = nomes.map(function (n) { return { id: cpUid('CAT'), name: n, parentId: null, type: 'DESPESA', accountingAccountId: null, dreGroup: null, costCenterId: centro.id, active: true, createdAt: now, updatedAt: now }; });
        cpCategories = cpCategories.concat(full);
        return putMany('cpcategories', full).then(function () { toast('Categorias cadastradas', nomes.length + ' categoria(s) em ' + centro.name); cpRenderBody(); });
      },
    });
  }

